 <section class="section"><div class="container"><div class="section-head"><div><span class="eyebrow">Industries</span><h2>Domain context that makes technology useful.</h2></div></div><div class="industry-grid">${industryData.map(x=>`<a class="industry" href="#/industries"><h3 style="color:white">${x.name}</h3><p>${x.text}</p></a>`).join("")}</div></div></section>
