function about(){return shell(`<main><section class="page-hero"><div class="container"><span class="eyebrow">About ARGsoft</span><p class="history-badge"><strong>Since 2018</strong> · Building technology partnerships with growing organizations.</p><h1>A technology partner built for the work between strategy and reality.</h1><p>ARGsoft Solutions combines consulting, engineering and technology talent to help organizations modernize with confidence.</p></div></section><section class="section"><div class="container split"><div><h2>We make complex technology easier to move.</h2><p class="lead">Our teams work alongside business and technology leaders to clarify priorities, build practical roadmaps and deliver the systems that matter.</p><p>We believe the best consulting leaves clients stronger: better architecture, better engineering habits, clearer operating models and better access to specialized talent.</p></div><div class="quote"><h3>Our mission</h3><p>Make technology transformation more practical, human and outcome-driven.</p><h3>Our vision</h3><p>Be the trusted technology partner organizations choose when the work is important and the path is complex.</p></div></div></section><section class="section alt"><div class="container"><div class="section-head"><div><span class="eyebrow">Values</span><h2>How we work.</h2></div></div><div class="cards">${["Own the outcome","Stay curious","Speak clearly","Build for trust"].map((x,i)=>`<article class="card"><div class="icon">0${i+1}</div><h3>${x}</h3><p>${["We take responsibility from first conversation through delivery.","We challenge assumptions and keep learning as technology changes.","We make decisions, risks and trade-offs visible to the people who need them.","Security, quality and reliability are part of delivery—not an afterthought."][i]}</p></article>`).join("")}</div></div></section><section class="section"><div class="container"><div class="section-head"><div><span class="eyebrow">Leadership</span><h2>Experienced people, close to the work.</h2></div><p>ARGsoft is designed around accountable leadership and teams that stay connected to client outcomes.</p></div><div class="cards"><article class="card"><div class="icon">AS</div><h3>Technology Leadership</h3><p>Guiding architecture, engineering quality and modernization strategy.</p></article><article class="card"><div class="icon">OP</div><h3>Delivery Leadership</h3><p>Keeping priorities, people, risks and execution aligned.</p></article><article class="card"><div class="icon">TA</div><h3>Talent Leadership</h3><p>Building recruiting and staffing programs around real technology needs.</p></article></div></div></section><section class="section"><div class="container cta"><div><h2>Let's build what matters.</h2><p>Bring us the challenge. We will bring a practical path forward.</p></div><a class="btn btn-teal" href="#/contact">Talk to Us →</a></div></section></main>`) }

function contact(){return shell(`<main><section class="page-hero"><div class="container"><span class="eyebrow">Contact</span><h1>Tell us what you are trying to accomplish.</h1><p>Whether you need a delivery partner, specialized engineering capability or technology talent, start with a conversation.</p></div></section><section class="section"><div class="container detail"><form class="panel" onsubmit="submitContact(event)"><h2 style="font-size:30px">Start a conversation</h2><div class="form-grid"><div class="field"><label>Name</label><input class="input" required></div><div class="field"><label>Work email</label><input class="input" type="email" required></div><div class="field"><label>Company</label><input class="input"></div><div class="field"><label>What do you need?</label><select class="select"><option>Technology consulting</option><option>Software development</option><option>Cloud / DevOps</option><option>Data / AI</option><option>Staffing / talent</option></select></div><div class="field full"><label>Message</label><textarea class="textarea" required placeholder="Briefly describe your challenge, timeline and goals."></textarea></div></div><button class="btn btn-primary" style="margin-top:18px">Send inquiry →</button><div id="contact-success" style="margin-top:15px"></div></form><aside class="panel"><h3>ARGsoft Solutions</h3><p>Technology consulting and talent solutions for modern organizations.</p><h3>Visit Our Office</h3><p>Flat No. 404, Sashi Arkade, JNTU Road, KPHB Phase - 9, Hyderabad - 500072, Telangana, India</p><h3>Email</h3><a class="link" href="mailto:hr@argsoft.net">hr@argsoft.net</a><h3>Careers</h3><p>Looking for your next technology opportunity?</p><a class="link" href="#/careers">Explore open roles →</a></aside></div></section></main>`) }
