function careers(){return shell(`<main><section class="page-hero"><div class="container"><span class="eyebrow">Careers</span><h1>Do meaningful technology work with people who care about the outcome.</h1><p>Interested in joining ARGsoft Solutions?<br>For career opportunities, please contact our HR team at <a class="link" href="mailto:hr@argsoft.net">hr@argsoft.net</a><br><br>Explore open opportunities across engineering, cloud, data, cybersecurity, enterprise applications and technology staffing.</p></div></section><section class="section"><div class="container"><div class="panel" style="max-width:820px;margin:0 auto;text-align:center;background:linear-gradient(135deg,#fffaf6,#fff7f0);border-color:#f0dfd0"><span class="eyebrow">Careers at ARGsoft</span><h2 style="font-size:34px;margin-top:14px">Interested in joining ARGsoft Solutions?</h2><p class="lead" style="margin:0 auto 20px">For career opportunities, please contact our HR team at <a class="link" href="mailto:hr@argsoft.net">hr@argsoft.net</a>.</p><a class="btn btn-teal" href="mailto:hr@argsoft.net?subject=Career%20Opportunity%20at%20ARGsoft%20Solutions">Contact HR →</a></div></div></section></main>`) }
function renderJobs(){const q=(document.querySelector("#job-q")?.value||"").toLowerCase(),l=document.querySelector("#job-l")?.value||"",t=document.querySelector("#job-t")?.value||"";const list=state.jobs.filter(j=>(!q||[j.title,j.id,j.location,j.skills.join(" ")].join(" ").toLowerCase().includes(q))&&(!l||j.location===l)&&(!t||j.type===t));document.querySelector("#jobs-list").innerHTML=list.length?list.map(j=>`<article class="job"><div><h3>${j.title}</h3><div class="job-meta"><span class="pill">${j.location}</span><span class="pill">${j.mode}</span><span class="pill">${j.type}</span><span class="pill">${j.experience}</span></div><small style="color:#7b8a9d">Posted ${j.posted} · ${j.id}</small></div><a class="btn btn-primary" href="#/job/${j.id}">View Job</a></article>`).join(""):`<div class="empty">No matching opportunities right now.</div>`}
function jobDetail(id){const j=state.jobs.find(x=>x.id===id);if(!j)return `<main><div class="container section"><h2>Job not found</h2><a class="btn btn-primary" href="#/careers">Back to Careers</a></div></main>`;return shell(`<main><section class="page-hero"><div class="container"><span class="eyebrow">${j.id}</span><h1>${j.title}</h1><div class="job-meta"><span class="pill">${j.location}</span><span class="pill">${j.mode}</span><span class="pill">${j.type}</span><span class="pill">${j.experience}</span><span class="pill">${j.rate}</span></div></div></section><section class="section"><div class="container detail"><article class="panel"><h2 style="font-size:30px">Role overview</h2><p>${j.description}</p><h3>Responsibilities</h3><ul>${j.responsibilities.map(x=>`<li>${x}</li>`).join("")}</ul><h3>Required skills</h3><div style="display:flex;gap:8px;flex-wrap:wrap">${j.skills.map(x=>`<span class="pill">${x}</span>`).join("")}</div><h3>Qualifications</h3><ul>${j.qualifications.map(x=>`<li>${x}</li>`).join("")}</ul></article><aside class="panel"><h3>Interested?</h3><p>Submit your profile and our recruiting team will review your application.</p><button class="btn btn-primary" style="width:100%" onclick="openApplication('${j.id}')">Apply Now →</button><a class="btn btn-ghost" style="width:100%;margin-top:10px" href="#/careers">← All jobs</a></aside></div></section></main>`) }
function openApplication(id){const j=state.jobs.find(x=>x.id===id);document.body.insertAdjacentHTML("beforeend",`<div class="modal-backdrop" id="app-modal"><div class="modal"><div class="modal-head"><div><span class="eyebrow">Application</span><h2 style="font-size:28px;margin-top:10px">${j.title}</h2></div><button class="close" onclick="document.querySelector('#app-modal').remove()">×</button></div><form onsubmit="submitApplication(event,'${j.id}')"><div class="form-grid"><div class="field"><label>Full name</label><input name="name" class="input" required></div><div class="field"><label>Email</label><input name="email" class="input" type="email" required></div><div class="field"><label>Phone</label><input name="phone" class="input" required></div><div class="field"><label>Location</label><input name="location" class="input"></div><div class="field"><label>LinkedIn URL</label><input name="linkedin" class="input" type="url"></div><div class="field"><label>Work authorization</label><select name="authorization" class="select"><option>Authorized to work in the U.S.</option><option>Requires sponsorship</option><option>Other</option></select></div><div class="field full"><label>Resume</label><input name="resume" class="input" type="file" accept=".pdf,.doc,.docx" required></div><div class="field full"><label>Cover letter</label><textarea name="cover" class="textarea" placeholder="Optional"></textarea></div></div><div class="notice" style="margin-top:15px">Prototype note: files are not uploaded to a server. Production should use secure cloud storage with signed upload URLs.</div><button class="btn btn-primary" style="margin-top:16px">Submit application</button><div id="apply-status" style="margin-top:12px"></div></form></div></div>`)}
function submitApplication(e,id){e.preventDefault();const f=new FormData(e.target);const j=state.jobs.find(x=>x.id===id);state.applicants.unshift({id:"APP-"+Math.floor(1000+Math.random()*9000),name:f.get("name"),email:f.get("email"),phone:f.get("phone"),location:f.get("location"),linkedin:f.get("linkedin"),position:j.title,date:new Date().toISOString().slice(0,10),status:"New",notes:"New application submitted through careers page."});persist();document.querySelector("#apply-status").innerHTML='<div class="notice success">Application submitted successfully. Thank you — ARGsoft recruiting will review your profile.</div>';e.target.reset()}
function hrLogin(){if(sessionStorage.getItem("arg_hr_session")==="1")return hrDashboard();return `<div class="login-wrap"><div class="login-card">${logo()}<div style="margin:30px 0 20px"><span class="eyebrow">HR Portal</span><h1 style="font-size:38px;margin:15px 0 8px">Sign in to recruiting operations.</h1><p style="color:var(--muted)">ARGsoft Solutions HR portal. Prototype authentication only; no username or password is hardcoded in the frontend.</p></div><form onsubmit="demoLogin(event)"><div class="field"><label>Email</label><input class="input" type="email" required placeholder="hr@company.com"></div><div class="field" style="margin-top:14px"><label>Password</label><input class="input" type="password" required placeholder="Enter password"></div><button class="btn btn-primary" style="width:100%;margin-top:18px">Sign in</button></form><button class="btn btn-ghost" style="width:100%;margin-top:10px" onclick="prototypeAccess()">Enter prototype HR portal</button><p style="font-size:12px;color:#7b8a9d;margin-top:20px">Production implementation should use a real identity provider/session service, not browser-only authentication.</p></div></div>`}
function demoLogin(e){e.preventDefault();prototypeAccess()}
function prototypeAccess(){sessionStorage.setItem("arg_hr_session","1");location.hash="#/hr";render()}
function hrShell(body){return `<div class="admin"><div class="admin-shell"><aside class="sidebar"><div class="side-logo">${logo().replace("color:var(--teal2)","color:var(--teal2)")}</div><a class="side-link active" href="#/hr">Dashboard</a><a class="side-link" href="#/hr/jobs">Jobs</a><a class="side-link" href="#/hr/applicants">Applicants</a><a class="side-link" href="#/hr/post">Post Job</a><a class="side-link" href="#/hr/settings">Settings</a><a class="side-link" href="#/hr-logout">Logout</a></aside><main class="admin-main">${body}</main></div></div>`}
function hrDashboard(){const counts={new:state.applicants.filter(a=>a.status==="New").length,interview:state.applicants.filter(a=>a.status==="Interview").length,selected:state.applicants.filter(a=>a.status==="Selected").length};return hrShell(`<div class="admin-top"><div><span class="eyebrow">HR Operations</span><h2>Recruiting dashboard</h2></div><button class="btn btn-primary" onclick="location.hash='#/hr/post'">+ Post Job</button></div><div class="admin-cards"><div class="admin-stat"><span>Active jobs</span><strong>${state.jobs.length}</strong></div><div class="admin-stat"><span>Applicants</span><strong>${state.applicants.length}</strong></div><div class="admin-stat"><span>New applications</span><strong>${counts.new}</strong></div><div class="admin-stat"><span>Interviews</span><strong>${counts.interview}</strong></div><div class="admin-stat"><span>Selected</span><strong>${counts.selected}</strong></div></div><div class="panel"><h3>Recent applicants</h3><div class="table-wrap"><table class="table"><thead><tr><th>Name</th><th>Position</th><th>Applied</th><th>Status</th></tr></thead><tbody>${state.applicants.slice(0,6).map(a=>`<tr><td>${a.name}</td><td>${a.position}</td><td>${a.date}</td><td><span class="status">${a.status}</span></td></tr>`).join("")}</tbody></table></div></div>`) }
function hrJobs(){return hrShell(`<div class="admin-top"><div><span class="eyebrow">Jobs</span><h2>Job management</h2></div><button class="btn btn-primary" onclick="location.hash='#/hr/post'">+ Post Job</button></div><div class="panel"><div class="filters"><input id="hr-job-q" class="input" placeholder="Search jobs" oninput="renderHrJobs()"><select id="hr-job-s" class="select" onchange="renderHrJobs()"><option value="">All statuses</option><option>Published</option><option>Closed</option></select></div><div id="hr-jobs-table"></div></div>`) }
function renderHrJobs(){const q=(document.querySelector("#hr-job-q")?.value||"").toLowerCase(),s=document.querySelector("#hr-job-s")?.value||"";const rows=state.jobs.filter(j=>(!q||[j.title,j.id,j.location].join(" ").toLowerCase().includes(q))&&(!s||s==="Published"));document.querySelector("#hr-jobs-table").innerHTML=`<div class="table-wrap"><table class="table"><thead><tr><th>Job</th><th>Location</th><th>Type</th><th>Status</th><th>Actions</th></tr></thead><tbody>${rows.map(j=>`<tr><td><b>${j.title}</b><br><small>${j.id}</small></td><td>${j.location}</td><td>${j.type}</td><td><span class="status">Published</span></td><td><div class="actions"><button class="btn btn-ghost small" onclick="editJob('${j.id}')">Edit</button><button class="btn btn-ghost small" onclick="closeJob('${j.id}')">Close</button><button class="btn btn-ghost small" onclick="deleteJob('${j.id}')">Delete</button></div></td></tr>`).join("")}</tbody></table></div>`}
function postJob(existing){const j=existing||{id:"ARG-"+Math.floor(1000+Math.random()*9000),title:"",location:"",mode:"Remote",type:"Full-time",experience:"",rate:"",posted:new Date().toISOString().slice(0,10),skills:[],description:"",responsibilities:[],qualifications:[]};return hrShell(`<div class="admin-top"><div><span class="eyebrow">${existing?"Edit Job":"Create Job"}</span><h2>${existing?"Update":"Post a new"} opportunity</h2></div><a class="btn btn-ghost" href="#/hr/jobs">Back to Jobs</a></div><form class="panel" onsubmit="saveJob(event,'${existing?existing.id:""}')"><div class="form-grid"><div class="field"><label>Job title</label><input name="title" class="input" value="${esc(j.title)}" required></div><div class="field"><label>Job ID</label><input name="id" class="input" value="${esc(j.id)}" required></div><div class="field"><label>Location</label><input name="location" class="input" value="${esc(j.location)}" required></div><div class="field"><label>Work model</label><select name="mode" class="select"><option ${j.mode==="Remote"?"selected":""}>Remote</option><option ${j.mode==="Hybrid"?"selected":""}>Hybrid</option><option ${j.mode==="Onsite"?"selected":""}>Onsite</option></select></div><div class="field"><label>Employment type</label><select name="type" class="select"><option ${j.type==="Full-time"?"selected":""}>Full-time</option><option ${j.type==="Contract"?"selected":""}>Contract</option><option ${j.type==="Contract-to-Hire"?"selected":""}>Contract-to-Hire</option></select></div><div class="field"><label>Experience</label><input name="experience" class="input" value="${esc(j.experience)}" required></div><div class="field"><label>Rate / salary</label><input name="rate" class="input" value="${esc(j.rate)}"></div><div class="field"><label>Skills (comma separated)</label><input name="skills" class="input" value="${esc(j.skills.join(", "))}"></div><div class="field full"><label>Description</label><textarea name="description" class="textarea" required>${esc(j.description)}</textarea></div><div class="field full"><label>Responsibilities (one per line)</label><textarea name="responsibilities" class="textarea">${esc(j.responsibilities.join("\n"))}</textarea></div><div class="field full"><label>Qualifications (one per line)</label><textarea name="qualifications" class="textarea">${esc(j.qualifications.join("\n"))}</textarea></div><div class="field"><label>Client name (optional/private)</label><input name="client" class="input" placeholder="Internal only"></div><div class="field"><label>Job status</label><select name="status" class="select"><option>Published</option><option>Closed</option></select></div></div><button class="btn btn-primary" style="margin-top:18px">${existing?"Save changes":"Publish job"} →</button></form>`) }
function esc(s){return String(s??"").replace(/[&<>"']/g,m=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#039;"}[m]))}
function saveJob(e,oldId){e.preventDefault();const f=new FormData(e.target),j={id:f.get("id"),title:f.get("title"),location:f.get("location"),mode:f.get("mode"),type:f.get("type"),experience:f.get("experience"),rate:f.get("rate")||"Competitive",posted:new Date().toISOString().slice(0,10),skills:String(f.get("skills")).split(",").map(x=>x.trim()).filter(Boolean),description:f.get("description"),responsibilities:String(f.get("responsibilities")).split("\n").map(x=>x.trim()).filter(Boolean),qualifications:String(f.get("qualifications")).split("\n").map(x=>x.trim()).filter(Boolean),client:f.get("client")};if(oldId){const idx=state.jobs.findIndex(x=>x.id===oldId);state.jobs[idx]=j}else state.jobs.push(j);persist();toast("Job saved");location.hash="#/hr/jobs"}
function editJob(id){location.hash="#/hr/edit/"+id}
function closeJob(id){const j=state.jobs.find(x=>x.id===id);if(j){j.closed=true;persist();toast("Job closed in prototype");render()}}
function deleteJob(id){if(confirm("Delete this job from the prototype?")){state.jobs=state.jobs.filter(x=>x.id!==id);persist();toast("Job deleted");render()}}
function hrApplicants(){return hrShell(`<div class="admin-top"><div><span class="eyebrow">Applicants</span><h2>Candidate pipeline</h2></div></div><div class="panel"><div class="filters"><input id="app-q" class="input" placeholder="Search candidates" oninput="renderApplicants()"><select id="app-s" class="select" onchange="renderApplicants()"><option value="">All statuses</option>${["New","Screening","Interview","Submitted","Selected","Rejected"].map(x=>`<option>${x}</option>`).join("")}</select></div><div id="apps-table"></div></div>`) }
function renderApplicants(){const q=(document.querySelector("#app-q")?.value||"").toLowerCase(),s=document.querySelector("#app-s")?.value||"";const rows=state.applicants.filter(a=>(!q||[a.name,a.email,a.position,a.location].join(" ").toLowerCase().includes(q))&&(!s||a.status===s));document.querySelector("#apps-table").innerHTML=`<div class="table-wrap"><table class="table"><thead><tr><th>Candidate</th><th>Position</th><th>Applied</th><th>Status</th><th>Action</th></tr></thead><tbody>${rows.map(a=>`<tr><td><b>${a.name}</b><br><small>${a.email}</small></td><td>${a.position}</td><td>${a.date}</td><td><select class="select" style="width:auto;padding:6px 8px" onchange="updateApplicant('${a.id}',this.value)">${["New","Screening","Interview","Submitted","Selected","Rejected"].map(x=>`<option ${x===a.status?"selected":""}>${x}</option>`).join("")}</select></td><td><button class="btn btn-ghost small" onclick="viewApplicant('${a.id}')">View</button></td></tr>`).join("")}</tbody></table></div>`}
function updateApplicant(id,status){const a=state.applicants.find(x=>x.id===id);if(a){a.status=status;persist();toast("Applicant status updated")}}
function viewApplicant(id){const a=state.applicants.find(x=>x.id===id);document.body.insertAdjacentHTML("beforeend",`<div class="modal-backdrop" id="cand-modal"><div class="modal"><div class="modal-head"><h2 style="font-size:30px">${a.name}</h2><button class="close" onclick="document.querySelector('#cand-modal').remove()">×</button></div><p><b>${a.position}</b> · ${a.location}</p><div class="form-grid"><div><small>Email</small><p>${a.email}</p></div><div><small>Phone</small><p>${a.phone}</p></div><div><small>LinkedIn</small><p><a class="link" href="${a.linkedin}" target="_blank">Profile ↗</a></p></div><div><small>Applied</small><p>${a.date}</p></div></div><div class="notice">Resume: prototype placeholder. Production should use a private object-storage URL with authorization checks.</div><h3>Recruiter notes</h3><textarea id="cand-notes" class="textarea">${esc(a.notes)}</textarea><button class="btn btn-primary" style="margin-top:12px" onclick="saveNotes('${a.id}')">Save notes</button></div></div>`)}
function saveNotes(id){const a=state.applicants.find(x=>x.id===id);a.notes=document.querySelector("#cand-notes").value;persist();document.querySelector("#cand-modal").remove();toast("Notes saved")}
function hrSettings(){return hrShell(`<div class="admin-top"><div><span class="eyebrow">Settings</span><h2>Prototype settings</h2></div></div><div class="panel"><h3>Backend readiness</h3><p>This prototype stores sample jobs and applicants in browser localStorage. It is intentionally not a secure production system.</p><div class="check-list">${["Replace localStorage with PostgreSQL/MySQL via REST API.","Use OIDC/SAML or another server-side identity provider for HR access.","Store resumes in private object storage and issue short-lived signed URLs.","Add audit logging for job and applicant changes.","Connect transactional email for applications and recruiter alerts."].map(x=>`<div class="check"><b>✓</b><span>${x}</span></div>`).join("")}</div></div>`) }
function logout(){sessionStorage.removeItem("arg_hr_session");location.hash="#/hr-login";render()}
function toast(msg){const x=document.createElement("div");x.className="toast";x.textContent=msg;document.body.appendChild(x);setTimeout(()=>x.remove(),2200)}

const INDUSTRY_DATA={"Healthcare & Life Sciences": {"icon": "01", "headline": "Reimagining healthcare operations with connected, secure, and patient-focused innovation", "description": "ARGsoft Solutions helps healthcare and life sciences organizations modernize technology while keeping patient experience, data protection, and operational efficiency at the center. We connect clinical, administrative, data, cloud, and enterprise systems to create a more integrated digital environment. Our teams help organizations improve workflows, strengthen information visibility, and build technology foundations that can support changing healthcare needs.", "success": "Supported a healthcare organization in streamlining digital workflows and improving operational data visibility, creating a stronger foundation for secure technology integration and better team collaboration.", "solutions": ["Healthcare application modernization", "Clinical and operational data platforms", "Healthcare data engineering & advanced analytics", "Cloud modernization and API integration", "Cybersecurity, privacy & compliance technology"]}, "BFSI": {"icon": "02", "headline": "Driving secure, compliant, and intelligent financial ecosystems", "description": "ARGsoft Solutions helps banking, financial services, and insurance organizations modernize legacy platforms, strengthen digital experiences, and improve the way critical financial data moves across the enterprise. We combine application engineering, data, cloud, automation, and security capabilities to support highly regulated environments. Our approach helps financial organizations improve operational efficiency while keeping reliability, risk management, compliance, and customer trust in focus.", "success": "Supported financial-services teams in improving application workflows, system integration, and data visibility across critical business functions while creating a stronger foundation for secure digital operations.", "solutions": ["Digital banking, insurance & financial applications", "AML, KYC, fraud prevention & risk technology", "Risk, compliance & regulatory analytics", "Data engineering, reporting & business intelligence", "Cloud, DevOps & core-system modernization"]}, "Retail & Consumer Goods": {"icon": "03", "headline": "Enhancing customer experience and supply-chain agility", "description": "ARGsoft Solutions helps retailers and consumer-goods organizations deliver connected customer experiences while improving visibility and efficiency across the value chain. We bring together commerce platforms, customer data, analytics, applications, inventory systems, and supply-chain technology. By connecting these capabilities, organizations can understand demand more effectively, personalize engagement, improve operational decisions, and respond faster to changing customer expectations.", "success": "Supported retail teams with application integration and improved visibility across customer, commerce, inventory, and operational workflows, helping teams make faster and more informed decisions.", "solutions": ["E-commerce & omnichannel commerce platforms", "Customer analytics & personalization", "Demand forecasting & advanced analytics", "Inventory and supply-chain optimization", "Cloud & enterprise application modernization"]}, "Manufacturing & Supply Chain": {"icon": "04", "headline": "Building resilient, intelligent, and connected operations", "description": "ARGsoft Solutions helps manufacturers modernize operations, improve visibility, and drive efficiency through data, automation, and connected enterprise technology. We connect production systems, ERP platforms, supply-chain applications, analytics, and cloud environments to create a more responsive operating model. Our teams help manufacturers improve information flow, reduce manual processes, and create technology foundations for smarter, more connected operations.", "success": "Supported manufacturing operations with technology modernization, connected data flows, and improved visibility across production and supply-chain processes, helping teams make operational decisions with greater confidence.", "solutions": ["Smart manufacturing & IoT integration", "Predictive analytics & intelligent automation", "Supply-chain visibility & integration", "ERP, SAP & enterprise application solutions", "Cloud, data & application modernization"]}};

function industryDetailHTML(name){
 const d=INDUSTRY_DATA[name];
 if(!d)return "";
 return `<span class="eyebrow">${d.icon} · ${name}</span>
 <h2>${d.headline}</h2>
 <p class="lead">${d.description}</p>
 <h3>Customer Success</h3>
 <p><em>${d.success}</em></p>
 <h3>Key Solutions</h3>
 <ul class="industry-list">${d.solutions.map(x=>`<li>${x}</li>`).join("")}</ul>
 <a class="btn btn-teal" href="#/contact">Talk to ARGsoft →</a>`;
}

function selectIndustry(name){
 const detail=document.getElementById("industry-detail");
 if(!detail || !INDUSTRY_DATA[name])return;
 detail.innerHTML=industryDetailHTML(name);
 document.querySelectorAll(".industry-tab").forEach(function(btn){
   const active=decodeURIComponent(btn.getAttribute("data-industry"))===name;
   btn.classList.toggle("active",active);
   btn.setAttribute("aria-pressed",active?"true":"false");
 });
}

function industries(selected){
 const names=Object.keys(INDUSTRY_DATA);
 const activeName=INDUSTRY_DATA[selected]?selected:names[0];
 const tabs=names.map(n=>`<button type="button" class="industry-tab ${n===activeName?"active":""}" data-industry="${encodeURIComponent(n)}" aria-pressed="${n===activeName}" onclick="selectIndustry(decodeURIComponent(this.getAttribute('data-industry')))"><span class="industry-icon">${INDUSTRY_DATA[n].icon}</span><span>${n}</span></button>`).join("");
 return shell(`<main>
 <section class="page-hero"><div class="container"><span class="eyebrow">Industries We Serve</span><h1>Technology solutions shaped around your industry.</h1><p>ARGsoft Solutions combines technology expertise with business context to help organizations modernize, connect systems and create measurable outcomes.</p></div></section>
 <section class="section"><div class="container industry-layout">
   <div class="industry-tabs" role="tablist" aria-label="Industries">${tabs}</div>
   <article class="industry-detail" id="industry-detail" aria-live="polite">${industryDetailHTML(activeName)}</article>
 </div></section>
 </main>`);
}
function router(){
 const raw=location.hash.replace(/^#/,"")||"/";
 const parts=raw.split("?");
 const r=parts[0];
 const params=new URLSearchParams(parts[1]||"");
 if(r==="/")return home();
 if(r==="/about")return about();
 if(r==="/services")return services();
 if(r==="/industries")return industries(params.get("industry"));
 if(r==="/careers")return careers();
 if(r==="/contact")return contact();
 if(r.startsWith("/service/"))return serviceDetail(r.substring(9));
 if(r.startsWith("/job/"))return jobDetail(r.split("/")[2]);
 if(r==="/hr-login")return hrLogin();
 if(r==="/hr-logout"){logout();return ""}
 if(r==="/hr"||r==="/hr/")return hrDashboard();
 if(r==="/hr/jobs")return hrJobs();
 if(r==="/hr/applicants")return hrApplicants();
 if(r==="/hr/post")return postJob();
 if(r.startsWith("/hr/edit/")){const j=state.jobs.find(x=>x.id===r.split("/")[3]);return postJob(j)}
 if(r==="/hr/settings")return hrSettings();
 return home();
}
function render(){document.querySelector("#app").innerHTML=router();if(location.hash==="#/careers")renderJobs();if(location.hash==="#/hr/jobs")renderHrJobs();if(location.hash==="#/hr/applicants")renderApplicants();window.scrollTo(0,0)}
window.addEventListener("hashchange",render);render();
